module protocol::whitelist_admin;

use protocol::app::{Self, AdminCap, ProtocolApp, PackageCallerCap};

const MAX_PERMISSION: u8 = 4;

public fun flash_loan(): u8 { 0 }
public fun enter_market_with_emode(): u8 { 1 }
public fun liquidation(): u8 { 2 }
public fun adl(): u8 { 3 }

public fun mint_new_whitelist(
    _: &AdminCap,
    app: &mut ProtocolApp,
    ctx: &mut TxContext,
): PackageCallerCap {
    let cap = app::mint_cap(ctx);

    app.ensure_version_matches();

    let whitelist = app.whitelist_mut();
    whitelist.insert(object::id(&cap), 0);

    cap
}

public fun burn_whitelist(
    app: &mut ProtocolApp,
    cap: PackageCallerCap,
) {
    app.ensure_version_matches();

    let whitelist = app.whitelist_mut();

    let cap_id = object::id(&cap);
    if (whitelist.contains(&cap_id)) {
        whitelist.remove(&cap_id);
    };
    app::burn_cap(cap);
}

public fun remove_whitelist(
    _: &AdminCap,
    app: &mut ProtocolApp,
    id: ID,
) {
    app.ensure_version_matches();

    let whitelist = app.whitelist_mut();
    whitelist.remove(&id);
}

public fun update_permission(
    _: &AdminCap,
    app: &mut ProtocolApp,

    id: ID,
    what: u8,

    is_grant: bool,
) {
    assert!(what < MAX_PERMISSION, protocol::error::invalid_params_error());
    app.ensure_version_matches();

    let whitelist = app.whitelist_mut();
    let permission = whitelist.get_mut(&id);

    let mask = 1u32 << what;

    if (is_grant) {
        *permission = *permission | mask;
    } else {
        let inverted = mask ^ 0xFFFFFFFF;
        *permission = *permission & inverted;
    };
}

